-- Rollback-only foreign QR/report records prove independent read/write boundaries.
BEGIN;
ALTER TABLE public.redirects DROP CONSTRAINT redirects_pending_tenant_fence;
ALTER TABLE public.redirect_domains DROP CONSTRAINT redirect_domains_pending_tenant_fence;
ALTER TABLE public.redirect_qr_image_links DROP CONSTRAINT redirect_qr_image_links_pending_tenant_fence;
ALTER TABLE public.redirect_qr_image_creation_log DROP CONSTRAINT redirect_qr_image_creation_log_pending_tenant_fence;
ALTER TABLE public.redirect_qr_assets DROP CONSTRAINT redirect_qr_assets_pending_tenant_fence;
ALTER TABLE public.redirect_qr_styles DROP CONSTRAINT redirect_qr_styles_pending_tenant_fence;
ALTER TABLE public.redirect_saved_reports DROP CONSTRAINT redirect_saved_reports_pending_tenant_fence;
ALTER TABLE public.redirect_report_shares DROP CONSTRAINT redirect_report_shares_pending_tenant_fence;
SET LOCAL ROLE service_role;
DO $$
DECLARE legacy uuid:='58aa4340-8f21-4b7f-9a10-90be2da89c01';other uuid:=gen_random_uuid();actor uuid:=gen_random_uuid();foreign_link uuid:=gen_random_uuid();foreign_domain uuid:=gen_random_uuid();foreign_image uuid:=gen_random_uuid();foreign_draft uuid:=gen_random_uuid();foreign_asset uuid:=gen_random_uuid();foreign_report uuid:=gen_random_uuid();foreign_share uuid:=gen_random_uuid();local_report uuid;local_version uuid;local_share uuid;foreign_version uuid;local_image uuid;result jsonb;snapshot jsonb;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor);INSERT INTO public.user_roles VALUES(actor,'admin');
 INSERT INTO public.redirect_workspaces(id,name,slug) VALUES(other,'QR report fixture','qr-report-fixture');
 INSERT INTO redirect_internal.workspace_owners(workspace_id,user_id) VALUES(other,actor);
 INSERT INTO public.redirects(id,workspace_id,type,slug,target) VALUES(foreign_link,other,'SHORT','foreign-qr-report','https://example.org/private-qr-report');
 INSERT INTO public.redirect_domains(id,workspace_id,hostname,created_by) VALUES(foreign_domain,other,'foreign-qr-report.example.com',actor);
 INSERT INTO public.redirect_qr_image_links(id,workspace_id,token_hash,creator_user_id,principal_key,link_id,label) VALUES(foreign_image,other,repeat('a',64),actor,'owner:'||actor,foreign_link,'Private QR image');
 INSERT INTO public.redirect_qr_image_links(id,workspace_id,token_hash,creator_user_id,principal_key,encoded_url,label,publication_state,draft_expires_at,logo_mode) VALUES(foreign_draft,other,repeat('b',64),actor,'owner:'||actor,'https://example.org/private-draft','Private QR draft','pending',clock_timestamp()+interval '15 minutes','custom');
 INSERT INTO public.redirect_qr_assets(id,workspace_id,target_scope,requested_by,mime,bytes,width,height,sha256,state) VALUES(foreign_asset,other,'workspace',actor,'image/png',8,1,1,repeat('c',64),'active');
 INSERT INTO public.redirect_qr_styles(workspace_id,scope,domain_id,style,logo_mode,logo_asset_id) VALUES(other,'workspace',NULL,'{"dots":"circle"}','custom',foreign_asset),(other,'domain:'||foreign_domain,foreign_domain,'{"dots":"circle"}','none',NULL);
 INSERT INTO public.redirect_saved_reports(id,workspace_id,owner_user_id,name,filters,visibility) VALUES(foreign_report,other,actor,'Private foreign report','{}','team') RETURNING version INTO foreign_version;
 INSERT INTO public.redirect_report_shares(id,workspace_id,report_id,owner_user_id,title,filters,link_ids,requires_workspace_owner) VALUES(foreign_share,other,foreign_report,actor,'Private foreign dashboard','{}',ARRAY[foreign_link],true);
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',legacy,'x-qg-redirect-session-actor',actor)::text,true);
 SELECT jsonb_build_object('images',(SELECT jsonb_agg(to_jsonb(q) ORDER BY id) FROM public.redirect_qr_image_links q),'assets',(SELECT jsonb_agg(to_jsonb(a) ORDER BY id) FROM public.redirect_qr_assets a),'styles',(SELECT jsonb_agg(to_jsonb(s) ORDER BY scope) FROM public.redirect_qr_styles s),'reports',(SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM public.redirect_saved_reports r),'shares',(SELECT jsonb_agg(to_jsonb(s) ORDER BY id) FROM public.redirect_report_shares s)) INTO snapshot;
 IF public.redirect_qr_image_resource('list',actor)->'data'<>'[]'::jsonb OR public.redirect_qr_image_link_json(foreign_image) IS NOT NULL OR public.redirect_qr_asset_json(foreign_asset) IS NOT NULL THEN RAISE EXCEPTION 'Foreign QR images/assets leaked';END IF;
 IF public.redirect_qr_effective_style()->>'dots'<>'square' OR public.redirect_qr_style_json()->>'logoMode'<>'inherit' OR public.redirect_qr_effective_logo()->>'logoSource'<>'default' THEN RAISE EXCEPTION 'Foreign workspace QR branding inherited';END IF;
 IF public.redirect_public_qr_image(repeat('a',64)) IS NOT NULL THEN RAISE EXCEPTION 'Inactive foreign public QR served';END IF;
 BEGIN PERFORM public.redirect_qr_image_resource('create',actor,p_values=>jsonb_build_object('linkId',foreign_link),p_hash=>repeat('d',64));RAISE EXCEPTION 'Foreign root QR image created';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_qr_image_resource('revoke',actor,p_id=>foreign_image,p_values=>jsonb_build_object('version',gen_random_uuid()));RAISE EXCEPTION 'Foreign QR image revoked';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_qr_image_draft(actor,NULL,foreign_draft);RAISE EXCEPTION 'Foreign draft obtained';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.reserve_redirect_qr_image_logo(actor,NULL,foreign_draft,gen_random_uuid(),'image/png',8,1,1,repeat('e',64));RAISE EXCEPTION 'Foreign draft upload reserved';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.finish_redirect_qr_image_logo(actor,NULL,foreign_draft,foreign_asset);RAISE EXCEPTION 'Foreign draft upload attached';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_qr_styles_for_links(ARRAY[foreign_link]);RAISE EXCEPTION 'Foreign root QR style obtained';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_qr_style_resource(actor,foreign_domain);RAISE EXCEPTION 'Foreign domain QR branding read';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.reserve_redirect_qr_logo(actor,foreign_domain,NULL,'image/png',8,1,1,repeat('e',64));RAISE EXCEPTION 'Foreign domain logo reserved';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.finish_redirect_qr_logo(actor,foreign_asset);RAISE EXCEPTION 'Foreign logo attached';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF public.redirect_saved_report_resource('list',actor,NULL,p_values=>'{"view":"all"}')->>'count'<>'0' THEN RAISE EXCEPTION 'Foreign report page/count leaked';END IF;
  BEGIN PERFORM public.redirect_saved_report_resource('get',actor,NULL,foreign_report);RAISE EXCEPTION 'Foreign report read';EXCEPTION WHEN no_data_found THEN NULL;END;
  BEGIN PERFORM public.redirect_saved_report_resource('run',actor,NULL,foreign_report);RAISE EXCEPTION 'Foreign report run';EXCEPTION WHEN no_data_found THEN NULL;END;
  BEGIN PERFORM public.redirect_saved_report_resource('patch',actor,NULL,foreign_report,jsonb_build_object('version',foreign_version,'name','denied'));RAISE EXCEPTION 'Foreign report changed';EXCEPTION WHEN no_data_found THEN NULL;END;
  BEGIN PERFORM public.redirect_saved_report_resource('delete',actor,NULL,foreign_report);RAISE EXCEPTION 'Foreign report deleted';EXCEPTION WHEN no_data_found THEN NULL;END;
  BEGIN PERFORM public.redirect_report_share_resource('list',actor,NULL,foreign_report);RAISE EXCEPTION 'Foreign report shares listed';EXCEPTION WHEN no_data_found THEN NULL;END;
  BEGIN PERFORM public.redirect_report_share_resource('create',actor,NULL,foreign_report);RAISE EXCEPTION 'Foreign report shared';EXCEPTION WHEN no_data_found THEN NULL;END;
  BEGIN PERFORM public.redirect_report_share_resource('revoke',actor,NULL,foreign_report,foreign_share);RAISE EXCEPTION 'Foreign report share revoked';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_report_share_ids(foreign_share);RAISE EXCEPTION 'Foreign share expanded';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_public_report_check(foreign_share,repeat('f',64));RAISE EXCEPTION 'Foreign public report password exposed';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_public_report_read(foreign_share,foreign_version,true,'{}');RAISE EXCEPTION 'Foreign public report read';EXCEPTION WHEN no_data_found THEN NULL;END;
 IF EXISTS(SELECT FROM public.redirect_report_budgets) THEN RAISE EXCEPTION 'Foreign report denial spent hashing/view budget';END IF;
 IF (SELECT jsonb_build_object('images',(SELECT jsonb_agg(to_jsonb(q) ORDER BY id) FROM public.redirect_qr_image_links q),'assets',(SELECT jsonb_agg(to_jsonb(a) ORDER BY id) FROM public.redirect_qr_assets a),'styles',(SELECT jsonb_agg(to_jsonb(s) ORDER BY scope) FROM public.redirect_qr_styles s),'reports',(SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM public.redirect_saved_reports r),'shares',(SELECT jsonb_agg(to_jsonb(s) ORDER BY id) FROM public.redirect_report_shares s)))<>snapshot THEN RAISE EXCEPTION 'Denied operations changed foreign QR/report state';END IF;
 -- A local report with an otherwise broad filter must not share foreign links.
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','local-qr-report','https://example.org/local-qr-report');
 result:=public.redirect_saved_report_resource('create',actor,NULL,p_values=>'{"name":"Local report","filters":{}}');local_report:=(result->>'id')::uuid;local_version:=(result->>'version')::uuid;
 result:=public.redirect_report_share_resource('create',actor,NULL,local_report,p_values=>jsonb_build_object('reportVersion',local_version,'title','Local share'));local_share:=(result->>'id')::uuid;
 IF (SELECT link_ids FROM public.redirect_report_shares WHERE id=local_share) @> ARRAY[foreign_link] OR cardinality(public.redirect_report_share_ids(local_share))<>1 THEN RAISE EXCEPTION 'Local broad share selected foreign roots';END IF;
 result:=public.redirect_qr_image_resource('create',actor,p_values=>'{"url":"https://example.org/local-qr"}',p_hash=>repeat('d',64));local_image:=(result->>'id')::uuid;
 IF NOT EXISTS(SELECT FROM public.redirect_qr_image_creation_log WHERE id=local_image AND workspace_id=legacy) OR NOT EXISTS(SELECT FROM public.redirect_qr_image_creation_log WHERE id=foreign_image AND workspace_id=other) THEN RAISE EXCEPTION 'QR creation trigger lost authoritative workspace';END IF;
END $$;
ROLLBACK;
